@page "/book-appointment"
@rendermode InteractiveServer
@using sv_65f9ff8e86ef48bb80b72df2c40e727d.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book a Medical Appointment</h3>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="book-appointment">
    <DataAnnotationsValidator />

    @* ───── STEP 1 ───── *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label for="patientName" class="form-label">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label for="email" class="form-label">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (serverErrors.TryGetValue(nameof(Model.Email), out var emailErr))
            {
                <div class="validation-message">@emailErr</div>
            }
        </div>

        <div class="mb-3">
            <label for="phone" class="form-label">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label for="insurance" class="form-label">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
        </div>
    </fieldset>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
            Next
        </button>
    }

    @* ───── STEP 2 ───── *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label for="doctor" class="form-label">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select"
                             @bind-Value="Model.PreferredDoctor"
                             @bind-Value:after="OnDoctorOrDateChanged">
                    <option value="">-- Select a doctor --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.PreferredDoctor" />
                @if (serverErrors.TryGetValue(nameof(Model.PreferredDoctor), out var docErr))
                {
                    <div class="validation-message">@docErr</div>
                }
            </div>

            <div class="mb-3">
                <label for="date" class="form-label">Date</label>
                <InputDate id="date" class="form-control"
                           @bind-Value="Model.AppointmentDate"
                           @bind-Value:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label for="timeSlot" class="form-label">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select a time slot --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (serverErrors.TryGetValue(nameof(Model.TimeSlot), out var slotErr))
                {
                    <div class="validation-message">@slotErr</div>
                }
            </div>

            <div class="mb-3">
                <label for="reason" class="form-label">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" rows="3"
                               @bind-Value="Model.ReasonForVisit" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </div>

            <div class="d-flex gap-2">
                <button type="button" class="btn btn-outline-secondary" @onclick="BackToStep1">
                    Back
                </button>
                <button type="button" class="btn btn-info" @onclick="CheckAvailability">
                    Check Availability
                </button>
                <button type="submit" class="btn btn-success" disabled="@(!availabilityChecked)">
                    Book Appointment
                </button>
            </div>
        </fieldset>
    }
</EditForm>

@if (submitted)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully!
    </div>
}

@code {
    private BookAppointmentModel Model { get; set; } = new();
    private bool showStep2;
    private bool submitted;
    private bool availabilityChecked;

    private List<string> doctors = [];
    private List<string> availableSlots = [];
    private Dictionary<string, string> serverErrors = new();

    private EditContext? editContext;

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(Model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate step-1 fields only
        editContext = new EditContext(Model);
        var step1Valid = true;

        if (string.IsNullOrWhiteSpace(Model.PatientName))
        {
            editContext.NotifyFieldChanged(editContext.Field(nameof(Model.PatientName)));
            step1Valid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.Email) || !IsValidEmail(Model.Email))
        {
            editContext.NotifyFieldChanged(editContext.Field(nameof(Model.Email)));
            step1Valid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.Phone))
        {
            editContext.NotifyFieldChanged(editContext.Field(nameof(Model.Phone)));
            step1Valid = false;
        }

        // DataAnnotationsValidator handles display; we just gate step 2
        var messageStore = new ValidationMessageStore(editContext);

        if (string.IsNullOrWhiteSpace(Model.PatientName))
            messageStore.Add(editContext.Field(nameof(Model.PatientName)), "Patient Name is required.");
        if (string.IsNullOrWhiteSpace(Model.Email))
            messageStore.Add(editContext.Field(nameof(Model.Email)), "Email is required.");
        else if (!IsValidEmail(Model.Email))
            messageStore.Add(editContext.Field(nameof(Model.Email)), "Invalid email format.");
        if (string.IsNullOrWhiteSpace(Model.Phone))
            messageStore.Add(editContext.Field(nameof(Model.Phone)), "Phone is required.");

        editContext.NotifyValidationStateChanged();

        if (step1Valid)
        {
            serverErrors.Clear();
            showStep2 = true;
            availabilityChecked = false;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        serverErrors.Clear();
    }

    private async Task OnDoctorOrDateChanged()
    {
        availabilityChecked = false;
        serverErrors.Remove(nameof(Model.PreferredDoctor));
        serverErrors.Remove(nameof(Model.TimeSlot));
        Model.TimeSlot = string.Empty;

        if (!string.IsNullOrEmpty(Model.PreferredDoctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService
                .GetAvailableTimeSlotsAsync(Model.PreferredDoctor, Model.AppointmentDate.Value);
        }
        else
        {
            availableSlots = [];
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        availabilityChecked = false;

        // Client-side step-2 validation
        editContext = new EditContext(Model);
        var messageStore = new ValidationMessageStore(editContext);
        var valid = true;

        if (string.IsNullOrWhiteSpace(Model.PreferredDoctor))
        {
            messageStore.Add(editContext.Field(nameof(Model.PreferredDoctor)), "Please select a doctor.");
            valid = false;
        }
        if (!Model.AppointmentDate.HasValue)
        {
            messageStore.Add(editContext.Field(nameof(Model.AppointmentDate)), "Date is required.");
            valid = false;
        }
        else if (Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            messageStore.Add(editContext.Field(nameof(Model.AppointmentDate)), "Date must be in the future.");
            valid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.TimeSlot))
        {
            messageStore.Add(editContext.Field(nameof(Model.TimeSlot)), "Please select a time slot.");
            valid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.ReasonForVisit))
        {
            messageStore.Add(editContext.Field(nameof(Model.ReasonForVisit)), "Reason for visit is required.");
            valid = false;
        }
        else if (Model.ReasonForVisit.Length > 500)
        {
            messageStore.Add(editContext.Field(nameof(Model.ReasonForVisit)), "Reason must be 500 characters or fewer.");
            valid = false;
        }

        editContext.NotifyValidationStateChanged();

        if (!valid)
            return;

        // Server-side validation
        serverErrors = await AppointmentService.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.PreferredDoctor,
            Model.TimeSlot);

        if (serverErrors.Count == 0)
        {
            availabilityChecked = true;
        }
    }

    private async Task HandleSubmit()
    {
        if (!availabilityChecked)
            return;

        // Re-run server validation to guard against stale state
        serverErrors = await AppointmentService.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.PreferredDoctor,
            Model.TimeSlot);

        if (serverErrors.Count > 0)
        {
            availabilityChecked = false;
            return;
        }

        submitted = true;
    }

    private static bool IsValidEmail(string email) =>
        System.Text.RegularExpressions.Regex.IsMatch(email,
            @"^[^@\s]+@[^@\s]+\.[^@\s]+$");
}

